export function driveEstimatorCsv(history){
 const columns=['received_at_ms','world_id','run_id','sim_s','state','fault','data_healthy','calibrated','localized','vx_mps','vy_mps','yaw_rad_s','gyro_bias_rad_s','odom_x_m','odom_y_m','odom_yaw_rad','map_x_m','map_y_m','map_yaw_rad','match_rms_m','match_age_s','unobserved_motion_s','fl_command_nm','fr_command_nm','rl_command_nm','rr_command_nm'];
 const rows=[];for(const e of history){const f=e.frame,d=f?.drive_estimator;if(!d)continue;const ready=d.state==='ready'&&d.data_healthy,located=ready&&d.localized,t=Array.from({length:4},(_,i)=>d.torque_commands_nm?.[i]??null);rows.push([e.received_at_ms,f.source.world_id,f.source.run_id,f.sim_time_s,d.state,d.fault_latched,d.data_healthy,d.calibrated,d.localized,...['vx_mps','vy_mps','yaw_rad_s'].map(k=>ready?d[k]:null),d.gyro_bias_rad_s,...['odom_x_m','odom_y_m','odom_yaw_rad'].map(k=>ready?d[k]:null),...['map_x_m','map_y_m','map_yaw_rad'].map(k=>located?d[k]:null),located?d.match_rms_m:null,d.match_age_s,d.unobserved_motion_s,...t].map(v=>v??'').join(','));}return {columns,rows,csv:columns.join(',')+'\n'+rows.join('\n')+'\n'};
}
